UPDATE project_access_grant SET status='REVOKED',effective_to=CURRENT_TIMESTAMP(6)
    WHERE project_id=#{projectId} AND grant_role_code='PROJECT_MODULE_EXPERT_ASSIGNMENT' AND status='ACTIVE'
    AND module_type=#{moduleType} AND round_no=#{roundNo}
    AND task_node_id=#{node}
      AND grantee_user_id IN #{id}
